<?php
namespace App\Tests\Controller;
use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;
final class GatewayControllerTest extends WebTestCase { public function testHealth():void{$c=static::createClient();$c->request('GET','/health');self::assertResponseIsSuccessful();self::assertJsonStringEqualsJsonString('{"status":"ok"}',$c->getResponse()->getContent());} public function testInvalidCoachRequest():void{$c=static::createClient();$c->request('POST','/api/v1/coach',server:['CONTENT_TYPE'=>'application/json'],content:'{"message":""}');self::assertResponseStatusCodeSame(400);self::assertStringContainsString('INVALID_REQUEST',$c->getResponse()->getContent());} public function testUnavailableUpstreamIsControlled():void{$c=static::createClient();$c->request('POST','/api/v1/coach',server:['CONTENT_TYPE'=>'application/json'],content:'{"message":"Hallo"}');self::assertResponseStatusCodeSame(503);self::assertStringContainsString('UPSTREAM_UNAVAILABLE',$c->getResponse()->getContent());} }
